  }, [isAdmin])

  useEffect(() => {
    void loadOrganization()
  }, [loadOrganization])

  const filteredMembers = useMemo(() => {
    const needle = query.toLowerCase().trim()
    if (!needle) return members
    return members.filter((member) => [memberName(member), member.email, member.role, member.title, member.location, ...(member.expertiseTags || [])].join(" ").toLowerCase().includes(needle))
