              <section className="peer-panel">
                <div className="border-b border-[var(--peer-line)] p-5"><p className="peer-eyebrow mb-2">Invitations</p><h2 className="font-display text-xl font-semibold">Pending and historical invites</h2></div>
                <div className="grid">
                  {invitations.length === 0 ? <EmptyState className="m-5 min-h-56 shadow-none" title="No invitations" description="Sent invitations will appear here." /> : invitations.map((invite) => (
