                <form onSubmit={sendInvite} className="grid gap-4 p-5"><div><label htmlFor="invite-email" className="text-xs font-bold">Company email address</label><input id="invite-email" type="email" required className="mt-2 h-11 w-full border border-[var(--peer-line)] bg-white px-3 text-sm" placeholder={`name@${organization?.domain || "company.com"}`} value={inviteEmail} onChange={(event) => setInviteEmail(event.target.value)} /><p className="mt-2 text-[11px] leading-5 text-[var(--peer-muted)]">Backend validation enforces the verified organization domain and seven-day invitation behavior.</p></div><div className="border border-[var(--peer-line)] bg-[var(--peer-surface-2)] p-4"><p className="text-[10px] font-bold uppercase text-[var(--peer-muted)]">Access preview</p><p className="mt-2 text-sm font-semibold">Member — standard organization access</p><p className="mt-1 text-xs leading-5 text-[var(--peer-muted)]">Administrator invitation selection is not exposed by the current send endpoint.</p></div><Button disabled={saving} className="bg-[var(--peer-teal)] text-white hover:bg-[var(--peer-navy-soft)]"><UserPlus className="size-4" />{saving ? "Sending…" : "Send invitation"}</Button></form>
